	rapier.undo.branch = envelope.branch.map(id => installedById.get(String(id)));
	rapier.undo.cursor = envelope.cursor;
	rapier.undo.earliestRevision = earliestRevision;
	rapier.undo.earliestHash = earliestHash;
	rapier.undo.trimReason = String(envelope.trimReason || '');
	rapier.undo.trimmedBytes = Number(envelope.trimmedBytes || 0);
	if (typeof envelope.sourceRootId === 'string' && envelope.sourceRootId) {
		_rapierResetSource(_rapierSourceText(), envelope.sourceRootId);
	}
