		if (cmd === 'quote') {
			return allQuoted ? body : body.split('\n').map(line => '> ' + line).join('\n');
		}
		if (cmd === 'p' || allAtLevel) return body;
		if (level) return '#'.repeat(level) + ' ' + body.replace(/[ \t]*\n+[ \t]*/g, ' ');
		return body;
