	if (!suffixEdge && (suffixRaw.length > lastBody.length || lastBody.slice(lastBody.length - suffixRaw.length) !== suffixRaw)) return bail();

	const firstSelected = prefixEdge ? prefixTail + firstBody.slice(prefixConsumed) : firstBody.slice(prefixRaw.length);
	const lastSelected = suffixEdge ? lastBody.slice(0, lastBody.length - suffixConsumed) + suffixHead : lastBody.slice(0, lastBody.length - suffixRaw.length);
