		documentAuthority: authority,
		realm,
		mode: rapier.view.mode,
		returnMode: rapier.view.sourceReturnMode === 'read' ? 'read' : 'edit',
		viewport,
		viewportRatio: _rapierClamp(Number(viewportRatio) || _RAPIER_VIEW_ANCHOR_RATIO, 0.1, 0.9),
		selection: _rapierTravelSelectionRecord(realm),
