		const total = _rapierTravelSourceLength(textarea);
		const windowStart = Math.max(0, start - _RAPIER_TRAVEL_REBASE_RADIUS);
		const windowEnd = Math.min(total, end + _RAPIER_TRAVEL_REBASE_RADIUS);
		const windowText = _rapierTravelSourceSlice(textarea, windowStart, windowEnd);
		const range = _rapierResolveAnchoredRange(
			windowText, current.anchor, start - windowStart, end - windowStart);
