		const target = current.target;
		if (target.startBlockId !== target.endBlockId) return null;
		const block = rapier.document.blocks.find(item => item.id === target.startBlockId);
		if (!block || String(block.raw || '').length > _RAPIER_TRAVEL_BLOCK_RESOLVE_LIMIT) return null;
		const textValue = _rapierBlockLiveText(block.id);
		if (textValue == null || textValue.length > _RAPIER_TRAVEL_BLOCK_RESOLVE_LIMIT) return null;
		const start = Math.max(0, Number(target.start) || 0);
		const end = Math.max(start, Number(target.end) || start);
		if (end - start > _RAPIER_TRAVEL_SELECTION_LIMIT) return null;
		const windowStart = Math.max(0, start - _RAPIER_TRAVEL_REBASE_RADIUS);
		const windowEnd = Math.min(textValue.length, end + _RAPIER_TRAVEL_REBASE_RADIUS);
		const range = _rapierResolveAnchoredRange(
			textValue.slice(windowStart, windowEnd), current.anchor,
			start - windowStart, end - windowStart);
