	if (!from) {
		showToast('Could not remember this place in the document', 'info');
		return true;
	}
	const source = direction < 0 ? _rapierTravelRuntime.back : _rapierTravelRuntime.forward;
	const destination = direction < 0 ? _rapierTravelRuntime.forward : _rapierTravelRuntime.back;
	_rapierTravelRuntime.ticketSerial++;
	let attempted = false;
	let compatible;
