	if (_rapierPersistenceCaptureBlocked() || !rapier.autosave.deferred) return false;
	const durable = rapier.autosave.deferredDurable;
	const snapshot = rapier.autosave.deferredSnapshot;
	rapier.autosave.deferred = false;
	rapier.autosave.deferredDurable = false;
	rapier.autosave.deferredSnapshot = false;
