		const button = document.createElement('button');
		button.type = 'button';
		button.tabIndex = -1;
		button.id = strip.id + '-' + position;
		button.className = 'command-palette__variant';
		button.setAttribute('role', 'option');
		button.setAttribute('aria-selected', index === state.activeIndex && position === state.variantIndex ? 'true' : 'false');
		button.setAttribute('aria-disabled', item.available ? 'false' : 'true');
