	if (_rapierMutationBarrierActive() || rapier.composition.block || rapier.composition.source) {
		showToast('Another edit is still being prepared', 'info');
		return true;
	}
	const guard = Object.freeze({
		..._rapierMutationStamp(),
		docKind: String(rapier.document.docKind || ''),
		mode: String(rapier.view.mode || ''),
		selectionStart: sourceTextarea.selectionStart,
		selectionEnd: sourceTextarea.selectionEnd,
		windowPrefixLength: _rapierHeavyWindowed() ? _rapierHeavyRuntime.window.startChar : -1,
	});
