	renderHistory();
	renderReadAloud();
	renderFilename();
	renderViewSurfaces();
	renderViewToggle();
	renderLineFurniture();
	renderVisibleSurfaces();
	renderCompare();
	renderEmbedChrome();
	renderFindBar();
	renderToolbar();
	renderPickers();
	renderEdgeSwipe();
	renderRecents();
	renderSettings();
	renderLicenses();
	renderRestore();
	renderProSheet();
	renderNavigator();
	renderMathPrompt();
	renderDocxPrompt();
	_rapierUiApplyReadOnly();
